// Parse registry and filter active blog sources
const raw = JSON.parse($input.first().json.data);
const activeSources = raw.sources.filter(s => s.active !== false);
return activeSources.map(s => ({ json: s }));

// Normalizes RSS/Atom/XML payload into uniform article items and generates deterministic SHA256 canonical hash
const crypto = require('crypto');
const source = $('Parse & Filter Active Sources').item.json;
const feedData = $input.first().json.data || $input.first().json;

function canonicalize(url) {
  if (!url) return '';
  try {
    const parsed = new URL(url.trim());
    parsed.search = '';
    parsed.hash = '';
    return parsed.toString().toLowerCase().replace(/\/$/, '');
  } catch (e) {
    return url.split('?')[0].split('#')[0].trim().toLowerCase();
  }
}

// Support both raw XML strings and pre-parsed feed objects
let items = [];
if (Array.isArray(feedData.items)) {
  items = feedData.items;
} else if (feedData.rss && feedData.rss.channel && feedData.rss.channel.item) {
  items = Array.isArray(feedData.rss.channel.item) ? feedData.rss.channel.item : [feedData.rss.channel.item];
} else if (feedData.feed && feedData.feed.entry) {
  items = Array.isArray(feedData.feed.entry) ? feedData.feed.entry : [feedData.feed.entry];
} else {
  items = [];
}

return items.slice(0, 5).map(item => {
  const rawUrl = item.link || (item.link && item.link['@_href']) || item.guid || item.id || '';
  const canonicalUrl = canonicalize(rawUrl);
  const hash = crypto.createHash('sha256').update(canonicalUrl).digest('hex');
  const title = (item.title && typeof item.title === 'string' ? item.title : (item.title && item.title['#text']) || '').trim();
  const pubDate = item.pubDate || item.published || item.updated || new Date().toISOString();
  const snippet = item.description || item.summary || item.content || '';

  return {
    json: {
      source_id: source.id,
      company: source.company,
      category: source.category,
      title,
      raw_url: rawUrl,
      canonical_url: canonicalUrl,
      article_hash: hash,
      pub_date: pubDate,
      snippet: typeof snippet === 'string' ? snippet.slice(0, 2000) : ''
    }
  };
});

